window.kbPageData["views/entry/k-a1fb1d1184ce1460"] = {"key":"entry/k-a1fb1d1184ce1460","state":{"route":"entry/k-a1fb1d1184ce1460"},"node":{"id":"k-a1fb1d1184ce1460","mode":"k","title":"城市治理智慧化精细化","type":"概念与词义","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["digital","governance","regional"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["社会治理"],"来源主题":["农业与城乡治理"],"资料类别":["非时政"]},"directorySummary":"4.城市治理智慧化精细化\n城市治理智慧化，就是以大数据、云计算、物联网等技术手段提升城市运行效率、公共\n服务质量和风险应对能力等，通过全域感知、智能研判和精准执行，让城市具备动态响应与\n自我优化的能力。城市治理精细化，则是兼顾科学管理与人本关怀，通过将治理对象、流程、\n责任落到最小单元，使治理更具温…","sources":[{"id":"43e04b6be1671410","label":"城市治理智慧化精细化","topic":"农业与城乡治理","category":"非时政","text":"4.城市治理智慧化精细化\n城市治理智慧化，就是以大数据、云计算、物联网等技术手段提升城市运行效率、公共\n服务质量和风险应对能力等，通过全域感知、智能研判和精准执行，让城市具备动态响应与\n自我优化的能力。城市治理精细化，则是兼顾科学管理与人本关怀，通过将治理对象、流程、\n责任落到最小单元，使治理更具温度、更加精细、更体现公平性，持续提升人民群众的获得\n感、幸福感、安全感。城市治理智慧化和精细化两者协同，有助于形成科学化、规范化、人\n性化的治理模式，推动城市治理更高效、更有序、更有温度。\n习近平总书记指出：“一流城市要有一流治理，要注重在科学化、精细化、智能化上下\n功夫。既要善于运用现代科技手段实现智能化，又要通过绣花般的细心、耐心、巧心提高\n精细化水平，绣出城市的品质品牌。”推动城市治理智慧化精细化，注重创新城市治理的理\n念、模式、手段，是深入践行人民城市理念的重要举措，是推进以人为本的新型城镇化的\n必然要求，是提升城市治理水平、推进城市治理现代化的重要方面。","source":{"doc":"6cbfb01fe723bba64b75","first":38,"last":39,"page":38,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"digital","title":"数字技术与公共生活"},{"slug":"regional","title":"区域协调与城乡融合"},{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-a1fb1d1184ce1460":[]}};
